/*
 * Qué ruta se reconcilia según la hora de Ciudad de México.
 *
 * Antes de las 15:00 se actualiza la ruta de ayer para conservar solamente
 * lo que todavía necesita atención. Desde las 15:00 se consulta la ruta nueva.
 * El tablero manda el día ya resuelto; este cálculo se usa en las dos corridas
 * automáticas, 07:15 y 15:00.
 */

const cuerpo = $json?.body ?? $json ?? {};
const pedido = typeof cuerpo.dia === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(cuerpo.dia)
  ? cuerpo.dia
  : null;
const ahora = new Date();
const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Mexico_City',
  year: 'numeric', month: '2-digit', day: '2-digit',
}).format(ahora);
const hora = Number(new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Mexico_City', hour: '2-digit', hourCycle: 'h23',
}).formatToParts(ahora).find((p) => p.type === 'hour')?.value);
const [anio, mes, fecha] = hoy.split('-').map(Number);
const ayer = new Date(Date.UTC(anio, mes - 1, fecha - 1)).toISOString().slice(0, 10);
const dia = pedido ?? (hora < 15 ? ayer : hoy);

return [{ json: { dia, origen: pedido ? 'tablero' : 'horario' } }];

/*
 * Paquetes a columnas de Postgres.
 *
 * La clasificación se calcula acá con la misma regla que
 * web/src/lib/tracker.ts, y se guarda para poder consultarla con SQL sin
 * reimplementarla. La pantalla igual la recalcula al leer: `PROXIMO` depende
 * de la ruta entera y cambia en cuanto el repartidor entrega, así que la
 * columna guardada envejece entre corrida y corrida. La columna sirve para
 * preguntarle a la base; el mapa se guía por lo recalculado.
 *
 * Si se cambia una regla, se cambia en los dos lados. La prueba
 * `npm run test:tracker` compara las dos salidas justamente para que no se
 * separen en silencio.
 */
/*
 * sync_id y día vienen pegados a cada fila que devolvió SQL Server, así que
 * en el camino normal no se cruza el grafo. El `$('...')` es solo el
 * respaldo para la corrida sin filas -ahí no hay fila de donde sacarlos- y
 * va dentro de un try/catch: si la cadena de items se cortó, n8n tira
 * «el nodo no se ejecutó», y eso no puede matar al flujo entero.
 */
const primera = $input.all()[0]?.json ?? {};
let sync = primera.SyncId ?? null;
let dia = primera.Dia ? String(primera.Dia).slice(0, 10) : null;

if (!sync || !dia) {
  try {
    sync = sync ?? $('Abrir sincronización').first().json.sync_id;
    dia = dia ?? String($('Abrir sincronización').first().json.dia).slice(0, 10);
  } catch {
    // Sin respaldo tampoco: se sigue con lo que haya. El cierre no va a
    // encontrar filas con este sync_id y no va a desactivar nada, que es
    // el comportamiento correcto cuando no se pudo leer nada.
  }
}

const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};
const entero = (v) =>
  v === null || v === undefined || v === '' || !Number.isFinite(Number(v))
    ? null
    : Math.trunc(Number(v));
const marca = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const bandera = (v) => v === true || v === 1 || v === '1' || v === 'true';

const coordenada = (lat, lon) => {
  const a = Number(lat);
  const b = Number(lon);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  if (a < -90 || a > 90 || b < -180 || b > 180) return null;
  if (a === 0 && b === 0) return null;
  return { lat: a, lon: b };
};

/*
 * El desenlace por nombre de estado.
 *
 * Es la misma tabla que `colorEstado` de web/src/lib/estados.ts, que se armó
 * contra los `EstadoViaje.NombreCompleto` que devuelve el sistema de verdad.
 * No hay una lista de IdEstado a propósito: los ids verificados en el proyecto
 * son 22 y 24 y los del filtro de fallidos, y completar el resto a ojo sería
 * inventar identificadores.
 */
const DESENLACE = {
  'entregado': 'ENTREGADO',
  'devuelto': 'NO_ENTREGADO',
  'devolucion': 'NO_ENTREGADO',
  'devolución': 'NO_ENTREGADO',
  'devolucion en centro de dropoff': 'NO_ENTREGADO',
  'devolución en centro de dropoff': 'NO_ENTREGADO',
  'pedido no entregado': 'NO_ENTREGADO',
  'siniestrado': 'NO_ENTREGADO',
  'en deposito': 'NO_ENTREGADO',
  'en depósito': 'NO_ENTREGADO',
  'en deposito con direccion incorrecta': 'NO_ENTREGADO',
  'en centro de dropoff': 'NO_ENTREGADO',
  'cancelado': 'CANCELADO',
  'retirado en camino a destino': 'EN_RUTA',
  'colectado': 'EN_RUTA',
  'para retirar': 'EN_RUTA',
  'por colectar': 'EN_RUTA',
  'reprogramado por comprador': 'NO_ENTREGADO',
};

const clasificar = (nombreEstado, visitado, activo) => {
  const desenlace = DESENLACE[String(nombreEstado ?? '').toLowerCase().trim()] ?? 'DESCONOCIDO';
  if (desenlace === 'CANCELADO') return 'CANCELADO';
  if (!activo) return 'RETIRADO_DE_RUTA';
  if (desenlace === 'ENTREGADO') return 'VISITADO_ENTREGADO';
  if (desenlace === 'NO_ENTREGADO') return visitado ? 'VISITADO_NO_ENTREGADO' : 'SIN_CLASIFICAR';
  if (desenlace === 'EN_RUTA') return visitado ? 'SIN_CLASIFICAR' : 'PENDIENTE_NO_VISITADO';
  return 'SIN_CLASIFICAR';
};

const filas = $input
  .all()
  .map((i) => i.json)
  .filter((r) => Number.isFinite(Number(r.IdViaje)) && Number(r.IdViaje) > 0);

let omitidos = 0;

const salida = filas.map((r) => {
  const destino = coordenada(r.LatitudDestino, r.LongitudDestino);
  if (!destino) omitidos += 1;

  const visitado = bandera(r.VisitadoMotoboy) || Boolean(r.FechaVisita);

  return {
    json: {
      hay: true,
      id_viaje: Number(r.IdViaje),

      // El tracking id es el mismo Viaje.Id, en texto: es como lo nombra la
      // operación y como viaja en los enlaces al operador.
      tracking_id: String(Number(r.IdViaje)),

      id_motoboy: entero(r.IdMotoboy),
      id_motoboy_balanceado: entero(r.IdMotoboyBalanceado),
      id_reserva: entero(r.IdReserva),
      id_ruta: entero(r.IdRuta),

      id_estado: entero(r.IdEstado),
      nombre_estado: texto(r.NombreEstado),

      // Se guarda como viene, nulo incluido. Completar un orden que el sistema
      // no declaró sería inventar la secuencia de la ruta.
      orden: entero(r.Orden),

      direccion: texto(r.Direccion),
      latitud_destino: destino?.lat ?? null,
      longitud_destino: destino?.lon ?? null,

      visitado,
      fecha_visita: marca(r.FechaVisita),
      clasificacion: clasificar(r.NombreEstado, visitado, true),

      fecha_ruta: dia,
      fecha_programado: marca(r.FechaProgramado),
      fecha_programado_hasta: marca(r.FechaProgramadoHasta),
      fecha_cambio_estado: marca(r.FechaCambioEstado),

      // Todo lo que la corrida encontró en la ruta está en la ruta. Los que
      // dejó de encontrar los apaga `tracker_cerrar_paquetes`, y solo si la
      // corrida terminó bien.
      activo_en_ruta: true,
      sync_id: sync,
    },
  };
});

for (const item of salida) {
  item.json.leidos = filas.length;
  item.json.omitidos = omitidos;
}

// Mismo testigo que en el flujo de repartidores, por el mismo motivo: sin
// items no hay nodo que se ejecute y la sincronización quedaría abierta.
// El testigo lleva sync_id y fecha porque el nodo que cierra los lee de su
// entrada directa, no de otro nodo.
return salida.length > 0
  ? salida
  : [{ json: { hay: false, leidos: 0, omitidos: 0, sync_id: sync, fecha_ruta: dia } }];

/*
 * El motivo de la falla, recortado y sin comillas, más el sync_id a mano.
 *
 * Esta rama es la última línea de defensa: es la que evita que una corrida
 * muerta deje su fila en `running` reteniendo el lock. Por eso no puede
 * reventar ella misma, y por eso el sync_id se resuelve acá adentro, con
 * try/catch, en vez de en la expresión del nodo que sigue.
 *
 * La diferencia importa: si `Abrir sincronización` no llegó a ejecutarse -el
 * flujo murió antes, o alguien corrió un nodo suelto desde el editor-, una
 * expresión `$('Abrir sincronización')` tira ExpressionError y se lleva puesta
 * a la propia rama de error. Un Code node puede atajarlo; una expresión no.
 *
 * Sin sync_id se sigue igual, con la cadena vacía: la consulta la convierte en
 * NULL y `tracker_fallar_sync` no encuentra ninguna fila que marcar. No hay
 * nada que cerrar, que es exactamente el caso.
 */
let sync = '';
try {
  sync = $('Abrir sincronización').first().json.sync_id ?? '';
} catch {
  sync = '';
}

/*
 * El mensaje se limpia por dos razones. Una es que se interpola en una consulta
 * y una comilla suelta la partiría al medio. La otra es que el error de un
 * driver de base puede traer la fila que estaba procesando, y de ahí a dejar un
 * domicilio guardado en la tabla de ejecuciones hay un paso. La función de
 * Postgres vuelve a recortar a 500: son dos redes para lo mismo, a propósito.
 */
const bruto = $json?.error?.message ?? $json?.error ?? 'El flujo se cortó sin detalle.';

const motivo = String(bruto)
  .replace(/['"\\]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 200) || 'El flujo se cortó sin detalle.';

return [{ json: { sync_id: String(sync), motivo } }];

const primera = $input.all()[0]?.json ?? {};
let sync = primera.SyncId ?? null; let dia = primera.Dia ? String(primera.Dia).slice(0, 10) : null;
if (!sync || !dia) { try { sync = sync ?? $('Abrir sincronización').first().json.sync_id; dia = dia ?? String($('Abrir sincronización').first().json.dia).slice(0, 10); } catch {} }
const texto = (v) => { const t = String(v ?? '').trim(); return t && t.toLowerCase() !== 'null' ? t : null; };
const entero = (v) => v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Math.trunc(Number(v));
const marca = (v) => { const d = new Date(v); return v && !Number.isNaN(d.getTime()) ? d.toISOString() : null; };
const bandera = (v) => v === true || v === 1 || v === '1' || v === 'true';
const destino = (lat, lon) => Number.isFinite(Number(lat)) && Number.isFinite(Number(lon)) && Number(lat) >= -90 && Number(lat) <= 90 && Number(lon) >= -180 && Number(lon) <= 180 && (Number(lat) !== 0 || Number(lon) !== 0) ? { lat: Number(lat), lon: Number(lon) } : null;
const desenlace = (n) => ({entregado:'ENTREGADO',devuelto:'NO_ENTREGADO','pedido no entregado':'NO_ENTREGADO',siniestrado:'NO_ENTREGADO','en deposito':'NO_ENTREGADO',cancelado:'CANCELADO','retirado en camino a destino':'EN_RUTA',colectado:'EN_RUTA','para retirar':'EN_RUTA','por colectar':'EN_RUTA'}[String(n ?? '').toLowerCase().trim()] ?? 'DESCONOCIDO');
const clasificar = (n, visitado) => { const d = desenlace(n); if (d === 'CANCELADO') return 'CANCELADO'; if (d === 'ENTREGADO') return 'VISITADO_ENTREGADO'; if (d === 'NO_ENTREGADO') return visitado ? 'VISITADO_NO_ENTREGADO' : 'SIN_CLASIFICAR'; return d === 'EN_RUTA' && !visitado ? 'PENDIENTE_NO_VISITADO' : 'SIN_CLASIFICAR'; };
const filas = $input.all().map((i) => i.json).filter((r) => Number(r.IdViaje) > 0); let omitidos = 0;
const salida = filas.map((r) => { const punto = destino(r.LatitudDestino, r.LongitudDestino); if (!punto) omitidos++; const visitado = bandera(r.VisitadoMotoboy) || Boolean(r.FechaVisita); return { json: { hay:true, id_viaje:Number(r.IdViaje), tracking_id:texto(r.TrackingId) ?? String(Number(r.IdViaje)), referencia_auxiliar:texto(r.ReferenciaAuxiliar), id_usuario:entero(r.IdUsuario), tienda:texto(r.Tienda), id_motoboy:entero(r.IdMotoboy), id_motoboy_balanceado:entero(r.IdMotoboyBalanceado), id_reserva:entero(r.IdReserva), id_ruta:entero(r.IdRuta), id_estado:entero(r.IdEstado), nombre_estado:texto(r.NombreEstado), orden:entero(r.Orden), direccion:texto(r.Direccion), telefono:texto(r.Telefono), ciudad:texto(r.Ciudad), barrio:texto(r.Barrio), codigo_postal:texto(r.CodigoPostal), observacion_direccion:texto(r.ObservacionDireccion), poligono:texto(r.Poligono), nombre_recibe:texto(r.NombreRecibe), comentario_motoboy:texto(r.ComentarioMotoboy), comentario_estado:texto(r.ComentarioEstado), motivo_no_entregado:texto(r.MotivoNoEntregado), motivo_no_devuelto:texto(r.MotivoNoDevuelto), evidencia_foto:texto(r.EvidenciaFoto), evidencia_tipo:texto(r.EvidenciaTipo), fecha_evidencia:marca(r.FechaEvidencia), latitud_destino:punto?.lat ?? null, longitud_destino:punto?.lon ?? null, visitado, fecha_visita:marca(r.FechaVisita), clasificacion:clasificar(r.NombreEstado, visitado), fecha_ruta:dia, fecha_programado:marca(r.FechaProgramado), fecha_programado_hasta:marca(r.FechaProgramadoHasta), fecha_cambio_estado:marca(r.FechaCambioEstado), activo_en_ruta:true, sync_id:sync, leidos:filas.length, omitidos } }; });
return salida.length ? salida : [{ json:{ hay:false, leidos:0, omitidos:0, sync_id:sync, fecha_ruta:dia } }];
